waza make_factorial() -> (int64) -> int64 {
    kaku factorial: (int64) -> int64 = waza (value: int64) -> int64 {
        moshi (value <= 1) {
            kaesu 1;
        }
        kaesu value * factorial(value - 1);
    };

    kaesu factorial;
}

kaku factorial = make_factorial();
chant(factorial(5));

sentaku Result<T, E> {
    Ok(T);
    Err(E);
}

waza get_value(result: Result<int64, string>) -> int64 {
    awase (result) {
        baai Ok(value) {
            kaesu value;
        }
        baai Err(message) {
            chant(message);
            kaesu 0;
        }
    }
}

kaku result: Result<int64, string> = Result.Ok(42);

chant(get_value(result));

sentaku Status {
    Ready;
    Failed(string);
}

kaku status: Status = Status.Ready();

awase (status) {
    baai Ready {
        chant("准备完成");
    }
    baai Failed(message) {
        chant(message);
    }
}

sentaku Message {
    Text(string);
    Number(int64);
}

kaku message: Message = Message.Text("Hello, Mio!");

awase (message) {
    baai Text(value) {
        chant(value);
    }
    baai Number(value) {
        chant(value);
    }
}

